(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return Packages.java.lang.Class.forName(n); } }
  function B(v){ return String(v) === 'true'; }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var out = { hasAutoJS: true, side: '', serverOk: false, levelOk: false, players: 0, modid: '', err: '' };
  try { out.side = String(AutoJS.side()); } catch (e) { out.err += 'side:' + e + ';'; }
  try { out.serverOk = (AutoJS.server() !== null); } catch (e) { out.err += 'server:' + e + ';'; }
  try { out.levelOk = (AutoJS.level() !== null); } catch (e) { out.err += 'level:' + e + ';'; }
  try { var ps = AutoJS.players(); out.players = (ps === null) ? 0 : ps.length; } catch (e) { out.err += 'players:' + e + ';'; }
  try {
    var oc = C('net.fabricmc.loader.api.FabricLoader').getInstance().getModContainer('astral_dice');
    out.modid = B(oc.isPresent()) ? String(oc.get().getMetadata().getId()) : '';
  } catch (e) { out.err += 'loader:' + e + ';'; }
  return out;
})()

